using System;using System.IO;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.SceneManagement;
public static class ClassroomDoodleBuilder {
 const string Root="Assets/StudyImmersive/Art/KIT/";
 [InitializeOnLoadMethod]static void Init(){if(File.Exists("Library/classroom-doodle.request"))EditorApplication.delayCall+=Run;}
 static void Check(bool v,string m){if(!v)throw new Exception(m);}
 static void Run(){if(!File.Exists("Library/classroom-doodle.request"))return;File.Delete("Library/classroom-doodle.request");try{
  var scene=SceneManager.GetActiveScene();Check(!EditorApplication.isPlayingOrWillChangePlaymode&&scene.path=="Assets/StudyImmersive/Scenes/GrandLibrary_Living.unity","Open actual scene in Edit mode");string backup=AssetDatabase.GenerateUniqueAssetPath("Assets/LibraryCharacter/Backups/GrandLibrary_before_classroom_doodles.unity");Check(EditorSceneManager.SaveScene(scene,backup,true),"Backup failed");
  var all=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var escape=all.Single(t=>t.name=="Maps").Find("Escape Room");Check(escape,"School missing");Check(!escape.Find("Classroom Whiteboards"),"Boards already installed");
  var wall=AssetDatabase.LoadAssetAtPath<Material>("Assets/LibraryCharacter/School/CampusTheme/Campus Wall.mat");var poster=AssetDatabase.LoadAssetAtPath<Material>(Root+"KIT Campus Notice.mat");Check(wall&&poster,"Required materials missing");int changed=0;
  foreach(var renderer in escape.GetComponentsInChildren<Renderer>(true)){var mats=renderer.sharedMaterials;bool found=false;for(int i=0;i<mats.Length;i++)if(mats[i]&&mats[i].name=="KIT Campus Notice"){mats[i]=wall;found=true;}if(found){Undo.RecordObject(renderer,"Remove repeated celebration notices");renderer.sharedMaterials=mats;changed++;}}
  Check(changed==3,"Unexpected notice surfaces: "+changed);
  var matsBoard=new Material[3];for(int i=0;i<3;i++){string texPath=Root+"ClassroomDoodle_"+(i+1)+".png";AssetDatabase.ImportAsset(texPath,ImportAssetOptions.ForceSynchronousImport);var texture=AssetDatabase.LoadAssetAtPath<Texture2D>(texPath);Check(texture,"Board texture missing: "+texPath);string matPath=Root+"Classroom Doodle "+(i+1)+".mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(matPath);if(!mat){mat=new Material(Shader.Find("Unlit/Texture"));AssetDatabase.CreateAsset(mat,matPath);}mat.mainTexture=texture;EditorUtility.SetDirty(mat);matsBoard[i]=mat;}
  var group=new GameObject("Classroom Whiteboards");Undo.RegisterCreatedObjectUndo(group,"Add classroom whiteboards");group.transform.SetParent(escape,false);
  Vector3[] positions={new Vector3(486.29f,1.78f,35f),new Vector3(513.71f,1.78f,35f),new Vector3(486.29f,1.78f,16.25f),new Vector3(491.21f,1.78f,1.25f),new Vector3(516.21f,1.78f,-12.5f)};
  Vector3[] normals={Vector3.right,Vector3.left,Vector3.right,Vector3.left,Vector3.left};
  for(int i=0;i<positions.Length;i++){var board=GameObject.CreatePrimitive(PrimitiveType.Quad);board.name="Classroom Doodle Board "+(i+1).ToString("00");board.transform.SetParent(group.transform,false);board.transform.SetPositionAndRotation(positions[i],Quaternion.LookRotation(-normals[i],Vector3.up));board.transform.localScale=new Vector3(1.9f,.95f,1);board.GetComponent<Renderer>().sharedMaterial=matsBoard[i%3];UnityEngine.Object.DestroyImmediate(board.GetComponent<Collider>());}
  var one=GameObject.CreatePrimitive(PrimitiveType.Quad);one.name="Celebration Notice - Entry";Undo.RegisterCreatedObjectUndo(one,"Add one celebration notice");one.transform.SetParent(escape,false);one.transform.SetPositionAndRotation(new Vector3(471.29f,1.52f,41f),Quaternion.LookRotation(Vector3.left,Vector3.up));one.transform.localScale=new Vector3(1.15f,1.15f,1);one.GetComponent<Renderer>().sharedMaterial=poster;UnityEngine.Object.DestroyImmediate(one.GetComponent<Collider>());
  Check(group.transform.childCount==5,"Expected five classroom boards");Check(group.GetComponentsInChildren<Collider>().Length==0&&!one.GetComponent<Collider>(),"Decorations must not block movement");EditorSceneManager.MarkSceneDirty(scene);Check(EditorSceneManager.SaveScene(scene),"Could not save scene");AssetDatabase.SaveAssets();Render(positions[0],normals[0]);File.WriteAllText("Tools/classroom-doodle-result.txt","PASS\nbackup="+backup+"\nrepeatedNoticeSurfacesRemoved="+changed+"\nclassroomBoards=5\ncelebrationNotices=1\n");Debug.Log("CLASSROOM_DOODLES_PASS boards=5 notice=1");
 }catch(Exception e){File.WriteAllText("Tools/classroom-doodle-result.txt","FAIL "+e);Debug.LogException(e);}}
 static void Render(Vector3 p,Vector3 normal){Directory.CreateDirectory("Design/KoreanCampus");var go=new GameObject("Whiteboard Preview"){hideFlags=HideFlags.HideAndDontSave};var cam=go.AddComponent<Camera>();cam.transform.position=p+normal*3+Vector3.down*.1f;cam.transform.LookAt(p);cam.fieldOfView=65;cam.nearClipPlane=.04f;cam.farClipPlane=50;var rt=new RenderTexture(1200,750,24);cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;var image=new Texture2D(1200,750,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1200,750),0,0);image.Apply();File.WriteAllBytes("Design/KoreanCampus/classroom-doodle.png",image.EncodeToPNG());cam.targetTexture=null;RenderTexture.active=null;UnityEngine.Object.DestroyImmediate(image);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(go);}
}
